<template><section class="summary-grid"><article v-for="item in cards" :key="item.label"><strong>{{item.value}}</strong><span>{{item.label}}</span></article></section></template>
<script setup>import { computed } from 'vue';const props=defineProps({summary:{type:Object,default:()=>({})}});const cards=computed(()=>[{label:'累计任务',value:props.summary.total_tasks||0},{label:'今日任务',value:props.summary.today_tasks||0},{label:'已完成',value:props.summary.status_counts?.completed||0},{label:'失败任务',value:props.summary.status_counts?.failed||0}])</script>
<style lang="scss" scoped>.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.summary-grid article{padding:15px;border:1px solid $border-color;border-radius:$border-radius-lg;background:#fff;box-shadow:$shadow-sm}.summary-grid strong,.summary-grid span{display:block}.summary-grid strong{color:$text-primary;font-size:24px}.summary-grid span{margin-top:4px;color:$text-secondary;font-size:13px}@media(max-width:700px){.summary-grid{grid-template-columns:repeat(2,1fr)}}</style>
